<script setup lang="ts">
import { ref } from 'vue'
import { Check, ArrowRight, Document, MagicStick, Loading } from '@element-plus/icons-vue'
import type { DemoRun } from './state'
defineProps<{ run: DemoRun }>()
const emit = defineEmits<{ confirm: [run: DemoRun]; reject: [run: DemoRun]; edit: [run: DemoRun]; task: [id: string]; knowledge: [id: string] }>()
const expanded = ref(false)
</script>
<template>
  <article class="demo-run-card">
    <div class="run-title"><span class="coo-symbol"><el-icon><MagicStick /></el-icon></span><strong>Coo</strong><span class="ai-note">AI 同事</span><time>{{ run.time }}</time></div>
    <button class="step-toggle" @click="expanded = !expanded"><span><el-icon v-if="run.status === 'done'" class="step-ok"><Check /></el-icon><el-icon v-else class="is-loading"><Loading /></el-icon>{{run.status==='done'?'已完成 4 个步骤':'正在调查'}}<small>查看过程</small></span><el-icon :class="{ turned: expanded }"><ArrowRight /></el-icon></button>
    <div v-if="expanded || run.status === 'running'" class="run-steps"><div v-for="(step,i) in run.steps" :key="step.tool" class="run-step" :class="step.status"><span class="step-mark"><el-icon v-if="step.status==='done'"><Check /></el-icon><el-icon v-else-if="step.status==='running'" class="is-loading"><Loading /></el-icon><template v-else>{{i+1}}</template></span><div><strong>{{step.name}}</strong><p>{{step.detail}}</p></div></div></div>
    <template v-if="run.status === 'done'">
      <p class="run-answer">{{ run.answer }}</p>
      <button v-if="run.sourceId" class="source-chip" @click="emit('knowledge',run.sourceId)"><el-icon><Document /></el-icon><span>订单超时未发货处理规范 <small>v2 · 项目知识</small></span><el-icon><ArrowRight /></el-icon></button>
      <section v-if="run.proposal" class="demo-proposal" :class="run.proposal.status">
        <div class="proposal-heading"><strong>{{run.proposal.kind==='task'?'建议创建跟进任务':run.proposal.kind==='comment'?'建议发表任务留言':'建议更新任务状态'}}</strong><span>{{run.proposal.status==='pending'?'待你确认':run.proposal.status==='accepted'?'已确认':'已拒绝'}}</span></div>
        <h4>{{run.proposal.title}}</h4><p>{{run.proposal.content}}</p>
        <div v-if="run.proposal.kind==='task'" class="proposal-meta"><span>负责人 <b>{{run.proposal.assignee}}</b></span><span>截止日期 <b>{{run.proposal.due}}</b></span><span class="priority">P1</span></div>
        <div v-if="run.proposal.kind==='status'" class="proposal-meta">目标状态 <b>{{run.proposal.taskStatus}}</b></div>
        <div v-if="run.proposal.status==='pending'" class="proposal-actions"><el-button type="primary" @click="emit('confirm',run)">确认{{run.proposal.kind==='task'?'创建任务':run.proposal.kind==='comment'?'发送留言':'更新状态'}}</el-button><el-button @click="emit('edit',run)">调整建议</el-button><button class="text-action" @click="emit('reject',run)">暂不执行</button></div>
        <button v-else-if="run.proposal.status==='accepted' && run.proposal.taskId" class="task-link" @click="emit('task',run.proposal.taskId)">打开关联任务 <el-icon><ArrowRight /></el-icon></button>
      </section>
    </template>
  </article>
</template>
<style scoped>
